-- Smithton food safety evidence. Existing administrator membership is the authority.
begin;
create table public.fs_audit_cycles (
 id uuid primary key default gen_random_uuid(),
 site text not null default 'Smithton' check(site='Smithton'),
 title text not null check(length(trim(title)) between 3 and 160),
 start_date date not null, end_date date not null, audit_due_on date not null,
 created_at timestamptz not null default now(), created_by uuid default auth.uid(),
 check(end_date>=start_date), unique(site,start_date,end_date)
);
create table public.fs_requirements (
 id text primary key, title text not null, category text not null, frequency text not null,
 evidence jsonb not null check(jsonb_typeof(evidence)='array'),
 fields jsonb not null default '[]' check(jsonb_typeof(fields)='array'),
 attachment_required boolean not null default false, sort_order integer not null
);
create table public.fs_records (
 id uuid primary key default gen_random_uuid(),
 cycle_id uuid not null references public.fs_audit_cycles(id),
 requirement_id text not null references public.fs_requirements(id),
 record_date date not null, title text not null check(length(trim(title)) between 3 and 200),
 performed_by text not null check(length(trim(performed_by)) between 2 and 160),
 outcome text not null default 'RECORDED' check(outcome in ('RECORDED','PASS','FAIL','PENDING')),
 batch_ref text not null default '', run_ref text not null default '', equipment_ref text not null default '',
 details jsonb not null default '{}' check(jsonb_typeof(details)='object'),
 notes text not null default '', corrective_action text not null default '', evidence_reference text not null default '',
 supersedes_id uuid unique references public.fs_records(id),
 created_at timestamptz not null default now(), created_by uuid not null default auth.uid(),
 check(length(notes)<=20000 and length(corrective_action)<=20000 and length(evidence_reference)<=2048),
 check(evidence_reference='' or evidence_reference ~ '^https://')
);
create table public.fs_attachments (
 id uuid primary key default gen_random_uuid(), record_id uuid not null references public.fs_records(id),
 object_path text not null unique, file_name text not null, mime_type text not null,
 size_bytes bigint not null check(size_bytes>0 and size_bytes<=20971520),
 created_at timestamptz not null default now(), created_by uuid not null default auth.uid()
);
create table public.fs_reviews (
 id uuid primary key default gen_random_uuid(), cycle_id uuid not null references public.fs_audit_cycles(id),
 requirement_id text not null references public.fs_requirements(id),
 status text not null check(status in ('reviewed','collecting','needs_action','not_applicable')),
 reason text not null default '', owner_name text not null default '', next_due_on date,
 created_at timestamptz not null default now(), created_by uuid not null default auth.uid(),
 check(status<>'not_applicable' or length(trim(reason))>=8)
);
create index fs_records_cycle_date on public.fs_records(cycle_id,record_date desc);
create index fs_records_requirement on public.fs_records(requirement_id,cycle_id,created_at desc);
create index fs_records_batch on public.fs_records(cycle_id,batch_ref) where batch_ref<>'';
create index fs_records_run on public.fs_records(run_ref) where run_ref<>'';
create index fs_attachments_record on public.fs_attachments(record_id);
create index fs_reviews_latest on public.fs_reviews(cycle_id,requirement_id,created_at desc);
-- A security-invoker trigger checks facts and retains immutable records, without granting privilege.
create function public.fs_validate_evidence() returns trigger language plpgsql security invoker set search_path='' as $$
declare c public.fs_audit_cycles; r public.fs_records; requirement public.fs_requirements; field jsonb; v jsonb;
begin
 if auth.uid() is null or not exists(select 1 from public.admin_users where user_id=auth.uid()) then raise exception 'Registered administrator required'; end if;
 new.created_by:=auth.uid(); new.created_at:=clock_timestamp();
 if tg_table_name='fs_records' then
  select * into c from public.fs_audit_cycles where id=new.cycle_id;
  if new.record_date<c.start_date or new.record_date>c.end_date then raise exception 'Record date must be inside the selected audit cycle'; end if;
  if new.record_date>(now() at time zone 'Australia/Hobart')::date then raise exception 'Evidence cannot be dated in the future'; end if;
  select * into requirement from public.fs_requirements where id=new.requirement_id;
  if new.requirement_id in ('harvest-record','stock-movements','relay-record','dispatch-label','stock-ledger','cold-chain','vibrio-control','depuration-run','harvest-hold') and length(trim(new.batch_ref))=0 then raise exception 'Batch reference required'; end if;
  if new.supersedes_id is not null then
   select * into r from public.fs_records where id=new.supersedes_id;
   if r.id is null or r.cycle_id<>new.cycle_id or r.requirement_id<>new.requirement_id then raise exception 'Correction must belong to the same audit cycle and evidence requirement'; end if;
  end if;
  for field in select value from jsonb_array_elements(requirement.fields) loop
   v:=new.details->(field->>'key');
   if (field->>'required')::boolean and (v is null or v='null'::jsonb or trim(v #>> '{}')='') then raise exception 'Required field: %',field->>'label'; end if;
   if v is not null and v<>'null'::jsonb and trim(v #>> '{}')<>'' then
    if field->>'type'='number' and jsonb_typeof(v)<>'number' then raise exception 'Numeric field required: %',field->>'label'; end if;
    if field->>'type'='number' and field->>'key'='quantity' and ((v #>> '{}')::numeric<=0 or (v #>> '{}')::numeric<>trunc((v #>> '{}')::numeric)) then raise exception 'Quantity must be a positive whole oyster count'; end if;
    if field->>'type'='select' and not (field->'options' ? (v #>> '{}')) then raise exception 'Invalid choice: %',field->>'label'; end if;
   end if;
  end loop;
  if new.requirement_id='stock-ledger' and ((new.details->>'quantity')::numeric<=0 or (new.details->>'quantity')::numeric<>trunc((new.details->>'quantity')::numeric)) then raise exception 'Stock movement requires a positive whole oyster count'; end if;
 elsif tg_table_name='fs_attachments' then
  select * into r from public.fs_records where id=new.record_id;
  if r.id is null or split_part(new.object_path,'/',1)<>r.cycle_id::text or split_part(new.object_path,'/',2)<>r.id::text then raise exception 'Attachment path does not match its evidence record'; end if;
  if not exists(select 1 from storage.objects o where o.bucket_id='smithton-food-safety' and o.name=new.object_path) then raise exception 'Upload the evidence file before linking it to the record'; end if;
 elsif tg_table_name='fs_reviews' and new.status='reviewed' then
  if not exists(select 1 from public.fs_records x where x.cycle_id=new.cycle_id and x.requirement_id=new.requirement_id and not exists(select 1 from public.fs_records y where y.supersedes_id=x.id)) then raise exception 'Collect evidence before signing off the review'; end if;
  select * into requirement from public.fs_requirements where id=new.requirement_id;
  if requirement.attachment_required and exists(select 1 from public.fs_records x where x.cycle_id=new.cycle_id and x.requirement_id=new.requirement_id and x.evidence_reference='' and not exists(select 1 from public.fs_records y where y.supersedes_id=x.id) and not exists(select 1 from public.fs_attachments a where a.record_id=x.id)) then raise exception 'Attach the supporting documents or an approved evidence link before review sign-off'; end if;
 end if;
 return new;
end $$;
revoke all on function public.fs_validate_evidence() from public, anon, authenticated;
create trigger fs_records_validate before insert on public.fs_records for each row execute function public.fs_validate_evidence();
create trigger fs_attachments_validate before insert on public.fs_attachments for each row execute function public.fs_validate_evidence();
create trigger fs_reviews_validate before insert on public.fs_reviews for each row execute function public.fs_validate_evidence();
alter table public.fs_audit_cycles enable row level security;
alter table public.fs_requirements enable row level security;
alter table public.fs_records enable row level security;
alter table public.fs_attachments enable row level security;
alter table public.fs_reviews enable row level security;
revoke all on public.fs_audit_cycles,public.fs_requirements,public.fs_records,public.fs_attachments,public.fs_reviews from anon,authenticated;
grant select,insert on public.fs_audit_cycles,public.fs_records,public.fs_attachments,public.fs_reviews to authenticated;
grant select on public.fs_requirements to authenticated;
create policy fs_cycles_read on public.fs_audit_cycles for select to authenticated using(exists(select 1 from public.admin_users where user_id=(select auth.uid())));
create policy fs_cycles_add on public.fs_audit_cycles for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.admin_users where user_id=(select auth.uid())));
create policy fs_requirements_read on public.fs_requirements for select to authenticated using(exists(select 1 from public.admin_users where user_id=(select auth.uid())));
create policy fs_records_read on public.fs_records for select to authenticated using(exists(select 1 from public.admin_users where user_id=(select auth.uid())));
create policy fs_records_add on public.fs_records for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.admin_users where user_id=(select auth.uid())));
create policy fs_attachments_read on public.fs_attachments for select to authenticated using(exists(select 1 from public.admin_users where user_id=(select auth.uid())));
create policy fs_attachments_add on public.fs_attachments for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.admin_users where user_id=(select auth.uid())));
create policy fs_reviews_read on public.fs_reviews for select to authenticated using(exists(select 1 from public.admin_users where user_id=(select auth.uid())));
create policy fs_reviews_add on public.fs_reviews for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.admin_users where user_id=(select auth.uid())));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('smithton-food-safety','smithton-food-safety',false,20971520,array['application/pdf','image/jpeg','image/png','image/heic','image/heif','text/plain','text/csv','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/zip','application/x-zip-compressed']);
create policy fs_private_files_read on storage.objects for select to authenticated using(bucket_id='smithton-food-safety' and exists(select 1 from public.admin_users where user_id=(select auth.uid())));
create policy fs_private_files_add on storage.objects for insert to authenticated with check(bucket_id='smithton-food-safety' and exists(select 1 from public.admin_users where user_id=(select auth.uid())) and exists(select 1 from public.fs_records r where r.id::text=(storage.foldername(name))[2] and r.cycle_id::text=(storage.foldername(name))[1]));
create policy fs_unlinked_upload_cleanup on storage.objects for delete to authenticated using(bucket_id='smithton-food-safety' and exists(select 1 from public.admin_users where user_id=(select auth.uid())) and not exists(select 1 from public.fs_attachments a where a.object_path=name));
